            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "As long as war is regarded as wicked, it will always have its fascination. When it is looked upon as vulgar, it will cease to be popular.", Author = "Oscar Wilde" },
