            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "Disobedience, in the eyes of any one who has read history, is man's original virtue. It is through disobedience that progress has been made, through disobedience and through rebellion.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "Sometimes the poor are praised for being thrifty. But to recommend thrift to the poor is both grotesque and insulting. It is like advising a man who is starving to eat less.", Author = "Oscar Wilde" },
