            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "Now, nothing should be able to harm a man except himself. Nothing should be able to rob a man at all. What a man really has, is what is in him. What is outside of him should be a matter of no importance.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "With the abolition of private property, then, we shall have true, beautiful, healthy Individualism. Nobody will waste his life in accumulating things, and the symbols for things. One will live. To live is the rarest thing in the world. Most people exist, that is all.", Author = "Oscar Wilde" },
