            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "There are as many perfections as there are imperfect men. And while to the claims of charity a man may yield and yet be free, to the claims of conformity no man may yield and remain free at all.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "There are three kinds of despots. There is the despot who tyrannises over the body. There is the despot who tyrannises over the soul. There is the despot who tyrannises over the soul and body alike. The first is called the Prince. The second is called the Pope. The third is called the People.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "Selfishness is not living as one wishes to live, it is asking others to live as one wishes to live.", Author = "Oscar Wilde" },
