            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "Women have become too brilliant. Nothing spoils a romance so much as a sense of humour in the woman. Or the want of it in the man.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "Discontent is the first step in the progress of a man or a nation.", Author = "Oscar Wilde" },
