            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "The only thing that can console one for being poor is extravagance. The only thing that can console one for being rich is economy.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "Ambition is the last refuge of the failure.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "Religions die when they are proved to be true. Science is the record of dead religions.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "If one tells the truth, one is sure, sooner or later, to be found out.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "Patriotism is the vice of nations.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "Only the shallow know themselves.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "In examinations the foolish ask questions that the wise cannot answer.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "The old believe everything; the middle-aged suspect everything; the young know everything.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "To love oneself is the beginning of a life-long romance.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "One should always be a little improbable.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "Time is a waste of money.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "The only way to atone for being occasionally a little over-dressed is by being always absolutely over-educated.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "Really, if the lower orders don't set us a good example, what on earth is the use of them?", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "I really don't see anything romantic in proposing. It is very romantic to be in love. But there is nothing romantic about a definite proposal. Why, one may be accepted. One usually is, I believe. Then the excitement is all over. The very essence of romance is uncertainty.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "Divorces are made in Heaven.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "The number of women in London who flirt with their own husbands is perfectly scandalous. It looks so bad. It is simply washing one's clean linen in public.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "I hear her hair has turned quite gold from grief", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "I do not approve of anything that tampers with natural ignorance. Ignorance is like a delicate exotic fruit; touch it and the bloom is gone.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "My dear fellow, the truth isn't quite the sort of thing one tells to a nice, sweet, refined girl.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "The only way to behave to a woman is to make love to her if she is pretty and to someone else if she is plain.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "Ah! That must be Aunt Augusta. Only relatives, or creditors, ever ring in that Wagnerian manner.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "To lose one parent may be regarded as a misfortune ... to lose both seems like carelessness.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "An engagement should come on a young girl as a surprise, pleasant or unpleasant as the case may be.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "All women become like their mothers. That is their tragedy. No man does. That's his.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "The truth is rarely pure and never simple. Modern life would be very tedious if it were either, and modern literature a complete impossibility!", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "I have invented an invaluable permanent invalid called Bunbury, in order that I may be able to go down into the country whenever I choose.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "In married life, three is company, and two is none.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "Of course the music is a great difficulty. You see, if one plays good music, people don't listen, and if one plays bad music people don't talk.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "It is absurd to have a hard and fast rule about what one should read and what one shouldn't. More than half of modern culture depends on what one shouldn't read.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "I have always been of opinion that a man who desires to get married should know either everything or nothing.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "Relations are simply a tedious pack of people, who haven't got the remotest knowledge of how to live, nor the smallest instinct about when to die.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "Mothers, of course, are all right. They pay a chap's bills and don't bother him. But fathers bother a chap and never pay his bills.", Author = "Oscar Wilde" },
            new Quote { Id = "https://en.wikiquote.org/wiki/Oscar_Wilde", Text = "Memory is the diary that we all carry about with us.", Author = "Oscar Wilde" },
        };
    }
